// Retrieve or initialize Digital Twin State
let twin = global.get('ac_twin') || {
    indoorTemp: 24.0,
    indoorHum: 50.0,
    outdoorTemp: 32.0,
    outdoorHum: 60.0,
    compTemp: 45.0,
    vibration: 'NORMAL',
    airQuality: 15.0,
    voltage: 230.0,
    current: 4.2,
    power: 966.0,
    energy: 14.5,
    espStatus: 'ONLINE',
    lastUpdated: new Date().toISOString()
};

let topic = msg.topic;
let payload = msg.payload;

// Update Twin State from MQTT Topics
if (topic === 'ac/indoor/temperature') twin.indoorTemp = parseFloat(payload) || twin.indoorTemp;
else if (topic === 'ac/indoor/humidity') twin.indoorHum = parseFloat(payload) || twin.indoorHum;
else if (topic === 'ac/outdoor/temperature') twin.outdoorTemp = parseFloat(payload) || twin.outdoorTemp;
else if (topic === 'ac/outdoor/humidity') twin.outdoorHum = parseFloat(payload) || twin.outdoorHum;
else if (topic === 'ac/compressor/temp') twin.compTemp = parseFloat(payload) || twin.compTemp;
else if (topic === 'ac/vibration') twin.vibration = String(payload).trim();
else if (topic === 'ac/airquality') twin.airQuality = parseFloat(payload) || twin.airQuality;
else if (topic === 'ac/status') {
    try {
        let s = JSON.parse(payload);
        twin.espStatus = s.status || 'ONLINE';
    } catch(e) { twin.espStatus = String(payload); }
}

twin.lastUpdated = new Date().toLocaleTimeString();
global.set('ac_twin', twin);

// ==========================================================================
// 1. COOLING EFFICIENCY CALCULATION
// ==========================================================================
let deltaT = twin.outdoorTemp - twin.indoorTemp;
let coolingEfficiency = 100.0;
if (deltaT > 0) {
    coolingEfficiency = Math.min(100, Math.max(20, (deltaT / 12.0) * 100.0));
}

// ==========================================================================
// 2. EXPLAINABLE RULE-BASED HEALTH SCORE ENGINE (0 - 100%)
// ==========================================================================
let healthScore = 100;
let faultList = [];
let recommendations = [];

// Check 1: Compressor Temperature Rules
if (twin.compTemp >= 75.0) {
    healthScore -= 40;
    faultList.push('CRITICAL: Compressor Overheating (' + twin.compTemp.toFixed(1) + '°C)');
    recommendations.push('Immediate shutdown required. Check condenser airflow, refrigerant charge, and fan motor.');
} else if (twin.compTemp >= 65.0) {
    healthScore -= 18;
    faultList.push('WARNING: Compressor High Temperature (' + twin.compTemp.toFixed(1) + '°C)');
    recommendations.push('Inspect outdoor unit heat exchanger for dirt/dust accumulation.');
}

// Check 2: Vibration Rules
if (twin.vibration === 'DETECTED' || twin.vibration === 'VIB_ACTIVE') {
    healthScore -= 22;
    faultList.push('WARNING: Abnormal Mechanical Vibration Detected');
    recommendations.push('Inspect compressor mounting dampers and blower fan balance.');
}

// Check 3: Air Quality / Filter Clog Indicator
if (twin.airQuality > 50.0) {
    healthScore -= 15;
    faultList.push('ALERT: Poor Indoor Air Quality / Filter Clogging Detected');
    recommendations.push('Clean or replace indoor AC filters to restore optimal airflow.');
} else if (twin.airQuality > 30.0) {
    healthScore -= 8;
    faultList.push('NOTICE: Moderate Air Quality Degradation');
}

// Check 4: Cooling Performance
if (twin.indoorTemp > 28.0 && twin.compTemp > 50.0) {
    healthScore -= 12;
    faultList.push('WARNING: Low Cooling Efficiency despite compressor active');
    recommendations.push('Check refrigerant pressure and expansion capillary tube.');
}

// Clamp Health Score to 0-100
healthScore = Math.max(0, Math.min(100, Math.round(healthScore)));

// Health Status Categorization
let statusCategory = 'HEALTHY';
let statusColor = '#4CAF50'; // Green
let nextServiceDays = 120;

if (healthScore >= 90) {
    statusCategory = 'HEALTHY';
    statusColor = '#4CAF50';
    nextServiceDays = 120;
} else if (healthScore >= 75) {
    statusCategory = 'GOOD';
    statusColor = '#2196F3'; // Blue
    nextServiceDays = 60;
} else if (healthScore >= 50) {
    statusCategory = 'WARNING';
    statusColor = '#FF9800'; // Amber
    nextServiceDays = 15;
} else {
    statusCategory = 'CRITICAL';
    statusColor = '#F44336'; // Red
    nextServiceDays = 1;
}

if (faultList.length === 0) {
    faultList.push('No Active Faults - Normal AC Operation');
    recommendations.push('Routine preventive maintenance scheduled.');
}

// Prepare Outputs for Dashboard
let outHealth = { payload: healthScore, topic: 'health_score', statusCategory: statusCategory, statusColor: statusColor };
let outStatus = { payload: statusCategory, color: statusColor, espStatus: twin.espStatus };
let outCompTemp = { payload: twin.compTemp, topic: 'comp_temp' };
let outIndoor = { payload: twin.indoorTemp, humidity: twin.indoorHum, topic: 'indoor_temp' };
let outOutdoor = { payload: twin.outdoorTemp, humidity: twin.outdoorHum, topic: 'outdoor_temp' };
let outVib = { payload: twin.vibration };
let outAQI = { payload: twin.airQuality };
let outCooling = { payload: Math.round(coolingEfficiency) };
let outNextService = { payload: nextServiceDays + ' Days' };
let outFaults = { payload: faultList.join(' | ') };
let outRecs = { payload: recommendations.join(' | ') };

return [
    outHealth,      // 1: Health Score
    outStatus,      // 2: Status Category
    outCompTemp,    // 3: Compressor Temp
    outIndoor,      // 4: Indoor Temp
    outOutdoor,     // 5: Outdoor Temp
    outVib,         // 6: Vibration
    outAQI,         // 7: Air Quality
    outCooling,     // 8: Cooling Efficiency
    outNextService, // 9: Next Service
    outFaults,      // 10: Fault Alerts
    outRecs         // 11: Maintenance Recommendation
];
